.mfp.mfp-invoice-blue.mfp-invoice-blue{--io-accent:#1B4F9B;--io-accent-soft:#2563C8;--io-page:#EBF1FA;--io-ink:#1A2333;--io-muted:#6B7A94;--io-line:#D4DCE8;--io-row:#F6F8FC;--io-card:#FFFFFF;
  width:100%;max-width:100%;box-sizing:border-box;font-family:Inter,'Segoe UI',system-ui,-apple-system,sans-serif!important;color:var(--io-ink)!important;font-weight:400!important;}
/* [pitfall 6] the DNN skin inherits font-weight:200 into the shell — every text element must state its own weight */
.mfp.mfp-invoice-blue.mfp-invoice-blue.mfp-invoice-blue{background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;margin:0!important;min-height:0!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue *{box-sizing:border-box;font-family:inherit!important;}
/* ── host chrome neutralisation ────────────────────────────────────────────
   The renderer wraps every form in .mf-form-wrapper > .mf-form-inner, and that inner element
   carries the standard white card (--mf-form-bg / --mf-form-border / --mf-form-shadow /
   --mf-form-padding / --mf-form-max-width). Around an invoice that already draws its own paper
   card it reads as a SECOND frame (owner: "card thừa bên ngoài form"). The shell lives INSIDE the
   wrapper, so reach back up with :has() — nothing else can select an ancestor. */
.mf-form-wrapper:has(.mfp-invoice-blue){background:transparent!important;padding:0!important;margin:0!important;box-shadow:none!important;border:0!important;border-radius:0!important;}
.mf-form-wrapper:has(.mfp-invoice-blue) .mf-form-inner,
.mf-form-wrapper:has(.mfp-invoice-blue) .mf-form{background:transparent!important;border:0!important;box-shadow:none!important;padding:0!important;margin:0!important;max-width:none!important;border-radius:0!important;}
.mf-form-wrapper:has(.mfp-invoice-blue) .mf-form-header{display:none!important;}
/* "Submitting…" is a SIBLING of the shell (#mf-loading-<id>), so by default it paints BELOW the
   card — outside the invoice. Confine it to the form zone: absolute over .mf-form-inner (which the
   rule above already stripped to a bare box around the shell), never over the host page chrome.
   Works whether the renderer toggles it to display:block or display:flex. */
.mf-form-wrapper:has(.mfp-invoice-blue) .mf-form-inner{position:relative!important;}
.mf-form-wrapper:has(.mfp-invoice-blue) .mf-loading{position:absolute!important;inset:0!important;z-index:20!important;
  background:color-mix(in srgb,#EBF1FA 90%,transparent)!important;color:#1B4F9B!important;
  font-weight:800!important;font-size:15px!important;text-align:center!important;padding-top:180px!important;margin:0!important;
  border-radius:16px!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-body,.mfp.mfp-invoice-blue.mfp-invoice-blue .io-head,.mfp.mfp-invoice-blue.mfp-invoice-blue .io-foot,.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group,.mfp.mfp-invoice-blue.mfp-invoice-blue label,.mfp.mfp-invoice-blue.mfp-invoice-blue span,.mfp.mfp-invoice-blue.mfp-invoice-blue div,.mfp.mfp-invoice-blue.mfp-invoice-blue input,.mfp.mfp-invoice-blue.mfp-invoice-blue select,.mfp.mfp-invoice-blue.mfp-invoice-blue textarea{font-weight:400;}
/* The invoice already paints its own centered .io-card. Keep this full-width
   layout wrapper transparent so it cannot read as a second outer card. */
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-page{background:transparent;padding:0;min-height:0;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-card{max-width:768px;margin:0 auto;background:var(--io-card);border-radius:16px;border:none;box-shadow:0 25px 50px -12px rgba(27,79,155,.18);overflow:hidden;}
/* header */
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-head{position:relative;display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:32px 32px 24px;background:#1B4F9B;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-blob{position:absolute;top:-40px;left:-40px;height:176px;width:176px;border-radius:9999px;opacity:.9;background:none;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-head-left,.mfp.mfp-invoice-blue.mfp-invoice-blue .io-head-right{position:relative;z-index:1;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-head-right{text-align:right;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-brand{display:flex;align-items:center;gap:8px;margin-bottom:4px;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-logo{display:flex;height:32px;width:32px;align-items:center;justify-content:center;border-radius:8px;background:var(--io-accent);color:#fff!important;font-size:12px;font-weight:900!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-brandname{font-size:18px;font-weight:900!important;letter-spacing:-.02em;color:var(--io-ink)!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-addr{font-size:12px;line-height:1.55;color:var(--io-muted)!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-kicker{font-size:12px;font-weight:500!important;color:var(--io-muted)!important;margin-bottom:4px;}
