.mfp.mfp-invoice-blue.mfp-invoice-blue .io-doctop{font-size:30px;font-weight:900!important;color:var(--io-ink)!important;line-height:1.05;letter-spacing:-.02em;}
/* decorative QR: sits on its own line under the header row, so .io-head drops its bottom padding
