.mfp.mfp-invoice-blue.mfp-invoice-blue .io-qr i.on{background:currentColor;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-meta{margin-top:8px;font-size:12px;line-height:1.55;color:var(--io-muted)!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-meta b{color:var(--io-ink)!important;font-weight:600!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-rule{height:6px;width:100%;background:linear-gradient(90deg,var(--io-accent),var(--io-accent-soft));}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-body{padding:24px 32px 28px;display:flex;flex-direction:column;gap:28px;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-two{display:grid;grid-template-columns:1fr 1fr;gap:32px;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-col{display:flex;flex-direction:column;gap:12px;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-sec{display:block;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-eyebrow{margin-bottom:8px;font-size:10px;font-weight:900!important;text-transform:uppercase;letter-spacing:.18em;color:var(--io-accent)!important;}

/* Section tag: a solid pill sitting on a full-width tinted band. Numbers come from the mock —
   the band is h-7 (28px) and the tag is px-4 py-1.5 at 10px font-black tracking-widest, so the
   pill is 28px tall and the band shows only beside it. */
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-eyebrow{display:flex!important;align-items:stretch!important;height:28px!important;margin-bottom:14px!important;padding:0!important;background:#EBF1FA!important;letter-spacing:0!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-eyebrow span{display:flex!important;align-items:center!important;padding:0 16px!important;background:#1B4F9B!important;color:#FFFFFF!important;font-size:10px!important;font-weight:900!important;text-transform:uppercase!important;letter-spacing:.1em!important;}
/* Banded header: the whole block is painted, so every glyph inside it must be re-inked — the
   theme bridge ships !important, and anything left unset falls back to page ink. The markup puts
   the two columns in .io-head-top and the address after it, so plain block flow stacks them. */
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-head{display:block!important;background:#1B4F9B!important;padding:26px 32px 22px!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-head-top{display:flex!important;align-items:flex-start!important;justify-content:space-between!important;gap:16px!important;margin-bottom:18px!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-head-right{text-align:right!important;position:relative;z-index:1;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-brand{margin-bottom:0!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-brandname,.mfp.mfp-invoice-blue.mfp-invoice-blue .io-doctitle,.mfp.mfp-invoice-blue.mfp-invoice-blue .io-kicker,.mfp.mfp-invoice-blue.mfp-invoice-blue .io-meta,.mfp.mfp-invoice-blue.mfp-invoice-blue .io-meta b{color:#FFFFFF!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-logo{background:rgba(255,255,255,.18)!important;color:#FFFFFF!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-addr-cols{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:16px!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-addr-k{display:block!important;font-size:11px!important;font-weight:700!important;color:#FFFFFF!important;margin-bottom:3px!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-addr-v{display:block!important;font-size:12px!important;color:rgba(255,255,255,.82)!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-rule{display:none!important;}
/* [pitfall 8 — NEW] .mf-field-group ships flex-basis:100%. Inside a flex-direction:column shell that is
   the MAIN size, so every field stretched to the full column height (measured 283px for a 53px field).
   Pin the basis back to content for every field inside this shell. */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group{flex:0 0 auto!important;}
/* [pitfall 2] MegaForm renders its own label — style it as the mock's tiny caps label instead of duplicating text */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group{margin:0 0 0 0!important;}
/* section-level fields are already titled by the .io-eyebrow — their own label would duplicate it */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='programme'] > .mf-field-label,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='items'] > .mf-field-label,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='interests'] > .mf-field-label,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='accommodation'] > .mf-field-label,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='motivation'] > .mf-field-label,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='grand_total'] > .mf-field-label,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='newsletter'] > .mf-field-label,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='terms'] > .mf-field-label{display:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-label{display:block!important;margin:0 0 4px!important;font-size:10px!important;font-weight:600!important;text-transform:uppercase!important;letter-spacing:.12em!important;color:var(--io-muted)!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-required{color:var(--io-accent)!important;}
/* [pitfall 5] real inputs are .mf-input/.mf-select — base CSS wins without specificity + !important */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-input,.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-select,.mfp.mfp-invoice-blue.mfp-invoice-blue input:not([type='checkbox']):not([type='radio']),.mfp.mfp-invoice-blue.mfp-invoice-blue select{
  width:100%!important;border:0!important;border-bottom:1px solid var(--io-line)!important;border-radius:0!important;
  background:transparent!important;padding:6px 0!important;font-size:14px!important;color:#1A2333!important;box-shadow:none!important;min-height:34px!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-input:focus,.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-select:focus,.mfp.mfp-invoice-blue.mfp-invoice-blue input:focus,.mfp.mfp-invoice-blue.mfp-invoice-blue select:focus{border-bottom:2px solid var(--io-accent)!important;outline:0!important;box-shadow:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue input::placeholder,.mfp.mfp-invoice-blue.mfp-invoice-blue textarea::placeholder{color:#9AA8BF!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-textarea,.mfp.mfp-invoice-blue.mfp-invoice-blue textarea{width:100%!important;border:1px solid var(--io-line)!important;border-radius:8px!important;background:transparent!important;padding:12px!important;font-size:14px!important;color:#1A2333!important;resize:vertical!important;min-height:92px!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-textarea:focus,.mfp.mfp-invoice-blue.mfp-invoice-blue textarea:focus{border-color:var(--io-accent)!important;box-shadow:0 0 0 3px color-mix(in srgb,var(--io-accent) 18%,transparent)!important;outline:0!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-error{color:#dc2626!important;font-size:11px!important;margin-top:4px!important;}
/* [pitfall 3] chips: base ships a 2-col grid — force a wrapping flex row */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='interests'] .mf-option-group{display:flex!important;flex-wrap:wrap!important;gap:8px!important;grid-template-columns:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='interests'] .mf-option-item{width:auto!important;margin:0!important;padding:0!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='interests'] .mf-option-ui{display:inline-flex!important;align-items:center!important;min-height:26px!important;padding:4px 12px!important;font-size:12px!important;border:1px solid var(--io-line)!important;border-radius:9999px!important;background:#FFFFFF!important;color:#1A2333!important;box-shadow:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='interests'] .mf-option-label{font-size:12px!important;font-weight:500!important;color:inherit!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='interests'] .mf-option-control:checked+.mf-option-ui{background:#1B4F9B!important;border-color:var(--io-accent)!important;color:#FFFFFF!important;}
/* cards (programme + accommodation) */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='programme'] .mf-option-group,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='accommodation'] .mf-option-group{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:12px!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='programme'] .mf-option-ui,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='accommodation'] .mf-option-ui{display:block!important;height:100%!important;padding:12px!important;border:2px solid var(--io-line)!important;border-radius:8px!important;background:#FFFFFF!important;text-align:left!important;box-shadow:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='accommodation'] .mf-option-ui{border-width:1px!important;text-align:center!important;font-size:12px!important;padding:10px 0!important;min-height:38px!important;display:flex!important;align-items:center!important;justify-content:center!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='programme'] .mf-option-label,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='accommodation'] .mf-option-label{font-size:12px!important;font-weight:700!important;color:#1A2333!important;line-height:1.25!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='accommodation'] .mf-option-label{font-weight:600!important;color:var(--io-muted)!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-option-desc{display:block!important;margin-top:2px!important;font-size:10px!important;font-weight:400!important;color:var(--io-muted)!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='programme'] .mf-option-control:checked+.mf-option-ui,
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='accommodation'] .mf-option-control:checked+.mf-option-ui{border-color:var(--io-accent)!important;background:#EBF1FA!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-field-group[data-key='programme'] .mf-option-control:checked+.mf-option-ui .mf-option-label{color:var(--io-accent)!important;}
/* [pitfall 4] the ✓ badge shows on every card — the mock has no tick at all, selection reads as border+tint */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mf-option-check{display:none!important;}
/* line-item grid — the DataGrid widget renders DIVs (.mfw-dgrid-*), never a <table> */
.mfp.mfp-invoice-blue.mfp-invoice-blue .io-items .mf-field-label{display:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid{border:0!important;background:transparent!important;box-shadow:none!important;display:flex!important;flex-direction:column!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-toolbar{order:2!important;justify-content:flex-start!important;padding:8px 0 0!important;border:0!important;background:transparent!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-title{display:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-add{border:0!important;background:transparent!important;color:var(--io-accent)!important;font-size:12px!important;font-weight:700!important;padding:0!important;box-shadow:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-grid{order:1!important;border:0!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-head{background:#EBF1FA!important;border:0!important;}
/* [StickyHeadOverlap v20260726] The widget styles head cells position:sticky;top:38px
   (megaform-widget-datagrid.ts:261) and the stickyHeader:false prop does NOT remove it. Sticky is
   contained by .mfw-dgrid-grid, which in an invoice is only ~2 rows tall, so the header slid its full
   38px DOWN and painted ON TOP of the first row (measured: natural y=1003 -> rendered y=1041, over an
   empty row occupying 1039-1085). An invoice table never scrolls on its own - pin it back to static.
   Selector is .mfw-dgrid-head .mfw-dgrid-cell, NOT .mfw-dgrid-head-cell: the widget also emits a
   6th, class-less div.mfw-dgrid-cell as the delete-column spacer (:493), which otherwise keeps the
   stock #f8fafc and reads as a white box at the end of the header row. */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-head .mfw-dgrid-cell{position:static!important;top:auto!important;z-index:auto!important;background:#EBF1FA!important;border:0!important;}
/* NOTE the order: border:0 must come BEFORE border-bottom, otherwise the shorthand resets the
   hairline back off and the rule-style table head loses its underline. */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-head-cell{background:#EBF1FA!important;color:#1B4F9B!important;font-size:10px!important;font-weight:900!important;text-transform:uppercase!important;letter-spacing:.08em!important;padding:8px 12px!important;border:0!important;}
/* a grid track's automatic minimum is its content's min-content size, and an <input> reports a
   sizeable one — without min-width:0 the cells would re-inflate the tracks minmax() just shrank. */
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-cell{padding:4px 12px!important;border:0!important;font-size:12px!important;min-width:0!important;overflow:hidden!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-cell input{min-width:0!important;max-width:100%!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-grid > div:nth-child(odd of :not(.mfw-dgrid-head)){background:var(--io-row)!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-cell input{border:0!important;border-bottom:0!important;background:transparent!important;font-size:12px!important;min-height:26px!important;padding:2px 0!important;box-shadow:none!important;}
.mfp.mfp-invoice-blue.mfp-invoice-blue .mfw-dgrid-empty{grid-column:1/-1!important;display:block!important;padding:14px 12px!important;color:var(--io-muted)!important;font-size:12px!important;background:transparent!important;border:0!important;position:static!important;}
/* the widget prints its own "Total (→ grand_total)" footer once totalFormula is set — the invoice
